	--LUA SEXPS

	mn.LuaSEXPs["GCW-callin"].Action = function (name, option) --checks called status (oncall), option specifies ships or wings

		if not GCW.isactive then return false end

		--the call in status is of a given ship or wing using the GCW lua table for that ship or wing. 

		local callready = false
		--first see if the GCW lua table is loaded, ie not empty, otherwise we have no values to check, also since ship is not here we can't use ship handle and have to use string
		if GCW.data[option][name] ~= nil and string.findAny(option, {"ships", "wings"}) then --can't use length of table since all keys are strings
			callready = GCW.data[option][name].oncall
			if callready == nil then
				callready = false
			end
		end
		return callready

	end

	mn.LuaSEXPs["GCW-update-battle"].Action = function () --runs battle update and checks what the mission status is and runs end outcomes when true

		--run mission over and outcome protocols
		--but first runs battle update
		if GCW.isactive and mn.isInCampaign() then

			GCW:Battle_RunUpdate() --always want this to run

		end

	end

	mn.LuaSEXPs["GCW-run-M1-end"].Action = function () --uses sexp to run OnEnd or OnStart M1 scripts when player clicks 'leave' method

		if not GCW.isactive then return end

		-- recall the "start" option is called via On Gameplay Start hook
		GCW:OnEnd_m_1()

	end

	mn.LuaSEXPs["compare-GCW-var-to-string"].Action = function (s_to_check, parent, child, childval)

		if not GCW.isactive then return false end

		local answer = false

		if s_to_check == nil or parent == nil or child == nil then
			return answer
		end

		local GCW_val

		if GCW.data[parent] ~= nil then
			if GCW.data[parent][child] ~= nil then

				--if we have a child val then we use it
				if childval ~= nil then
					if GCW.data[parent][child][childval] ~= nil then
						GCW_val = GCW.data[parent][child][childval]
					end
				else

				--if we didn't have a child val then we just stick with child
					GCW_val = GCW.data[parent][child]
				end

				--convert called val to string and shorten if need be
				--only do this if the value is a number, string, or bool, as making a table string might cause issues
				if type(GCW_val) == "string" or type(GCW_val) == "string" or type(GCW_val) == "number" then
					GCW_val = tostring(GCW_val)
					if #GCW_val >= 32 then
						GCW_val = string.sub(GCW_val,1,32)
					end
				end

				--finally check values
				--print("Comparing GCW variable: "..tostring(GCW_val).." to string input: "..tostring(s_to_check).."\n")
				if GCW_val == s_to_check then
					answer = true
				end

			end
		end
		--print("Returning "..tostring(answer).."\n")
		return answer

	end

	mn.LuaSEXPs["get-GCW-number-variable"].Action = function (parent, child, childval)

		if not GCW.isactive then return 0 end

		local val = 0
		local GCWval

		if parent == nil or child == nil then
			return val
		end

		if GCW.data[parent] ~= nil then
			if GCW.data[parent][child] ~= nil then
				--if we have a child val then we use it
				if childval ~= nil then
					if GCW.data[parent][child][childval] ~= nil then
						GCWval = GCW.data[parent][child][childval]
					end
					else
				--if we didn't have a child val then we just stick with child
					GCWval = GCW.data[parent][child]
				end
				if type(GCWval) == "number" then
					val = GCWval
				end
			end
		end
		--print("Got GCW number value:"..tostring(val).."\n")
		return val

	end

	mn.LuaSEXPs["set-GCW-from-variable"].Action = function (val_to_set, parent, child, childval)

		if not GCW.isactive then return end

		local function toboolean(str)
			local converted = false
			if str == "True" or str == "true" then
				converted = true
			end
			return converted
		end

		local GCW_val

		if parent ~= nil and child ~= nil and val_to_set ~= nil then
			if GCW.data[parent] ~= nil then
				if GCW.data[parent][child] ~= nil then
					--if we have a child val then we use it
					if childval ~= nil then
						if GCW.data[parent][child][childval] ~= nil then
							GCW_val = GCW.data[parent][child][childval]
						end
						else
					--if we didn't have a child val then we just stick with child
						GCW_val = GCW.data[parent][child]
					end

					--check what type the oOG var was and set new type accordingly
					--if type(GCW_val) == "string" then
					--end
					if type(GCW_val) == "number" then
						val_to_set = tonumber(val_to_set)
					end
					if type(GCW_val) == "boolean" then
						val_to_set = toboolean(val_to_set)
					end

					--now we have to change the value of the global variable
					if GCW.data[parent][child][childval] ~= nil then
						GCW.data[parent][child][childval] = val_to_set
						else
						GCW.data[parent][child] = val_to_set
					end
		--print("Changed GCW variable to: "..tostring(val_to_set).."\n")
				end
			end
		end
	end

	mn.LuaSEXPs["set-variable-from-GCW"].Action = function (sx_var_to_set, parent, child, childval) --sx_var_to_set is the variable handle

		if not GCW.isactive then return end

		if parent == nil or child == nil or sx_var_to_set == nil then
			return
		end
		--get GCW value
		local GCWval
		if GCW.data[parent] ~= nil then
			if GCW.data[parent][child] ~= nil then
				--if we have a child val then we use it
				if childval ~= nil then
					if GCW.data[parent][child][childval] ~= nil then
						GCWval = GCW.data[parent][child][childval]
					end
					else
				--if we didn't have a child val then we just stick with child
					GCWval = GCW.data[parent][child]
				end
			end
		end

		--set that value to the sexp var specified
		if sx_var_to_set:isValid() and GCWval ~= nil then
			sx_var_to_set.Value = GCWval
			GCW:VariableCacheUpdate(sx_var_to_set.Name, GCWval)
		end

	end

	mn.LuaSEXPs["modify-variable-GCW-string"].Action = function (sx_var_to_set, value) --sx_var_to_set is the variable handle

		if not GCW.isactive then return end

		--set that value to the sexp var specified
		if sx_var_to_set:isValid() and value ~= nil then
			GCW:UpdateVariable(tostring(sx_var_to_set), value, true)
		end

	end

	mn.LuaSEXPs["modify-variable-GCW-number"].Action = function (sx_var_to_set, value) --sx_var_to_set is the variable handle

		if not GCW.isactive then return end

		--set that value to the sexp var specified
		if sx_var_to_set:isValid() and value ~= nil then
			GCW:UpdateVariable(tostring(sx_var_to_set), value, true)
		end

	end

	mn.LuaSEXPs["GCW-number-oncall-or-called"].Action = function(callstatus, basenameorteam, shipsize, smallmodifier)

		if not GCW.isactive then return 0 end

		shipsize = shipsize or ""
		if callstatus == "oncall" or callstatus == "called" then
			local l_team = ""
			local l_basename = ""
			if basenameorteam ~= nil then
				if basenameorteam == "Friendly" or basenameorteam == "Hostile" then
					l_team = basenameorteam
				else
					l_basename = basenameorteam
				end
			end
			local toptions = { size=shipsize, team=l_team, basename=l_basename, list_as_string=false }
			local cc = GCW:Count_Call(toptions)
			local num = cc.oncall.ships.sum_all
			if smallmodifier == "bombers" or smallmodifier == "fighters" then
				num = cc[callstatus].ships[smallmodifier]
				if num == nil then
					GCW:warning("GCW number-oncall-or-called LUA SEXP provided number of oncall ships for "..tostring(smallmodifier).." because that key is nil for GCW:Count_Call(), returning 0...\n")
					num = 0
				end
			end
			return num
		else
			GCW:warning("GCW Number-oncall-or-called LUA SEXP input of callstatus is not 'oncall' or 'called', returning 0...\n")
			return 0
		end

	end

	mn.LuaSEXPs["GCW-set-play-message"].Action = function(sendername, message_base, delay, pr_str)

		if not GCW.isactive then return end

		GCW:GetPlay_Message(sendername, message_base, delay, pr_str)


	end

	mn.LuaSEXPs["GCW-player-by-dockable-ship"].Action = function ()

		if not GCW.isactive then 
			return false
		end

		local answer = false
		local as_big_f_table = GCW.battle_status.active_ships.Friendly.big
		local ply = FotG:GetPlayerShip()
		local dock_dist = GCW.cv.ply_trigger_dock_distance
		if as_big_f_table ~= nil and #as_big_f_table > 0 and ply ~= nil and ply:isValid() and ply:getBreedName() == "Ship" then
			local ply_pos = ply.Position
			for _,v_ship in ipairs(as_big_f_table) do 
				local sname = v_ship.as_self_name
				local gcws = GCW.data.ships[sname]
				if gcws ~= nil then 
					--is it dockable?
					if GCW:ShipClass_ExternalFighterDock(gcws.class) or GCW:ShipClass_InternalFighterDock(gcws.class) then
						--are we close enough?
						local t_ship = mn.Ships[sname]
						if t_ship ~= nil and t_ship:isValid() and not t_ship:isDying() and not t_ship:isDepartingWarp() then
							if ply_pos:getDistance(t_ship.Position) <= dock_dist then
								answer = true
								break
							end
						end
					end
				end
			end
		end

		return answer

	end

	mn.LuaSEXPs["GCW-ply-dock-var-update"].Action = function() --ran once the player has pressed the dock key, so mission will fade out within 1-2 seconds

		if not GCW.isactive then return end

		--check if this mission type wants us to do that
		local mtype = GCW.data.player.mission_type
		local count_dock_as_depart = GCW:tget(mtype, {"mission_meta", "player_dock_adds_depart"})
		if count_dock_as_depart then
			--say that all valid ships have left, we do this because
			--if two big ships are leaving at the same time, then the player may press dock before either has a chance to depart
			--so pretend like they both left
			--that way it counts them for the end mission depart variables
			local as_big_f_table = GCW.battle_status.active_ships.Friendly.big
			if as_big_f_table ~= nil and #as_big_f_table > 0 then
				--recall, when this function is run the mission is in the process of fading out
				local mn_ships = mn.Ships
				for _,v_ship in ipairs(as_big_f_table) do
					--remove from depart queue so as to not trigger twice
					GCW:JumpQueue_Remove(v_ship.as_self_name)
					GCW:OnShipDorD(mn_ships[v_ship.as_self_name], false, false) --second arg is if it's dead or not, default is false
				end
			end
		end

	end

	mn.LuaSEXPs["GCW-add-to-jump-queue"].Action = function (ship, priority, option) --not used ATM

		if not GCW.isactive then return end

		if ship ~= nil and ship:isValid() and not ship:isDying() then
			--if already on list it will not add it again
			local teamname = GCW:TeamHelper(ship.Team.Name)
			GCW:JumpQueue_Add(ship, priority, option, teamname)
		end

	end

	mn.LuaSEXPs["GCW-add-to-intel"].Action = function (ship, intel_type)

		if not GCW.isactive then return end
		if ship ~= nil and ship:isValid() and not ship:isDying() then
			--update intel type with tracker, only counts for big hostile ships since that is what is in the SEXP!
			--Intel type: 1 = scanned, 2 = tagged --NAV_HELP 8821
			local teamname = GCW:TeamHelper(ship.Team.Name)
			if teamname == "Hostile" then
				local m_vars = GCW.mission.sexp_vars.Intel_Tracking
				local sname = ship.Name
				if intel_type == 1 then
					--scanned, count right away
					--update tracker and note that this ship was counted
					if GCW.battle_status.intel_gathered_ships.hostiles_scanned[sname] == nil then
						GCW.battle_status.intel_gathered_ships.hostiles_scanned[sname] = true
						GCW:UpdateVariable(m_vars.hostile_scanned_count, 1)
						GCW:UpdateVariable(m_vars.hostile_to_scan, -1)
						--already a target next unscanned key, and it shows up in hud target view
						--so perhaps do not need display name icon string addition like tagged
					end
				elseif intel_type == 2 then
					--tagged, count right away but then remove if ship dies
					--update tracker and note that this ship was counted
					if GCW.battle_status.intel_gathered_ships.hostiles_tagged[sname] == nil then
						GCW.battle_status.intel_gathered_ships.hostiles_tagged[sname] = true
						--play sound and send confirmation message
						ad.playSound(ad.getSoundentry(8))
						GCW:GetPlay_TrainingMessage("tagged_success", 4)
						--also update active tag tracker
						GCW:UpdateVariable(m_vars.hostile_tagged_count, 1)
						GCW:UpdateVariable(m_vars.hostile_to_tag, -1)
						ship.DisplayName = ship.DisplayName .. "*"
						--also need way to ensure AI leaves this ship alone
						--  switch to tactical target and turret protect ship?
						--  or just guardian ship?
						--or just turret protect, and the small AI was never told to actually destroy it
						--  though if no opposing fighters then it may get attacked via the 'attack any' order
						--for now just protect the ship, and if the player orders it attacked then fine
						--NAV_HELP 5213
						if GCW:vv(GCW.mission.sexp_vars.mission_type_helper) == GCW.cv.overall_m_types.overall_recon then
							ship:setFlag(true, "protect-ship", "laser-protect-ship", "missile-protect-ship", "beam-protect-ship")
						end
					end
				end
			end
		end

	end

	--Script State

	Script_State = {}

	function Script_State:Engage()

		ba.postGameEvent(ba.GameEvents["GS_EVENT_SCRIPTING_MISSION"])

	end

	function Script_State:Exit(extra_exit_function)

		ba.postGameEvent(ba.GameEvents["GS_EVENT_PREVIOUS_STATE"])

		if extra_exit_function ~= nil then
			extra_exit_function()
		end

	end

	function Script_State:Get_Previous_State()

		return self.previous_state_name

	end

	function Script_State:UpdateMousePressed(reset)

		if reset then
			self.clicked_mouse_position = {-1, -1}
		else
			self.clicked_mouse_position = {io.getMouseX(), io.getMouseY()}
		end

	end

	function Script_State:Tracker_Reset(hv_old_state) --, hv_new_state, show_cursor

		self.script_state_time = 0
		self.escape_menu_up = false

		if hv_old_state ~= nil then
			self.previous_state_name = hv_old_state.Name
		else
			self.previous_state_name = nil
		end

		self:UpdateMousePressed(true)

		--do not actually need to do this anymore
		--if show_cursor then
			--io.setCursorHidden(false, true)
		--else
			--io.setCursorHidden(true, true)
		--end

	end

	function Script_State:Time_Update()

		self.script_state_time = self.script_state_time + ba.getRealFrametime()

	end

	function Script_State:Time_Get()

		return self.script_state_time

	end

	function Script_State:On_Frame()

		self:Time_Update()

	end

	--GCW

	GCW = {}

	GCW.Version = 15.8 --only needs to change if json file structure changes
	GCW.Subversion = 3 --just for tracking which version folks are on without any structural changes
	GCW.isactive = false

	function GCW:vv(sexp_var_name, no_cache)

		if sexp_var_name ~= nil then
			if no_cache then
				return mn.SEXPVariables[sexp_var_name].Value
			else
				local bs = self.battle_status
				if bs ~= nil then
					return bs.cached_sxv_lua[sexp_var_name].Value
				else
					self:warning("Get Variable function called before battle status table initiated!")
					return nil
				end
			end
		else
			print("GCW Warning: get variable function called with non existant variable <"..tostring(sexp_var_name)..">, returning 0 \n")
			return 0
		end

	end

	function GCW:TrackerVariablesTable()

		--cache sexp var table to speed things up
		local bs = self.battle_status
		if bs == nil then
			self:warning("Tracker variables table function called before battle status table initiated!")
			return {}
		end
		local sv = self.battle_status.cached_sxv_lua --mn.SEXPVariables --used cached list to keep things optimized

		--set values, do full written out version so reference lookup works
		local ftbl = {
			big={
				oncall = sv["Friend-Big-Oncall"].Value,
				departed = sv["Friend-Big-Depart"].Value,
				dead = sv["Friend-Big-Dead"].Value,
				activesum = sv["Friend-Big-ActiveSum"].Value,
				called = sv["Friend-Big-Entered"].Value,
				dod = sv["Friend-Big-Dead"].Value + sv["Friend-Big-Depart"].Value
			},
			small={
				oncall = sv["Friend-Small-Oncall"].Value,
				departed = sv["Friend-Small-Depart"].Value,
				dead = sv["Friend-Small-Dead"].Value,
				activesum = sv["Friend-Small-ActiveSum"].Value,
				called = sv["Friend-Small-Entered"].Value,
				dod = sv["Friend-Small-Dead"].Value + sv["Friend-Small-Depart"].Value
			},
			s1={
				oncall = sv["Friend-S1-Oncall"].Value,
				departed = sv["Friend-S1-Depart"].Value,
				dead = sv["Friend-S1-Dead"].Value,
				activesum = sv["Friend-S1-ActiveSum"].Value,
				called = sv["Friend-S1-Entered"].Value,
				dod = sv["Friend-S1-Dead"].Value + sv["Friend-S1-Depart"].Value
			},
			s2={
				oncall = sv["Friend-S2-Oncall"].Value,
				departed = sv["Friend-S2-Depart"].Value,
				dead = sv["Friend-S2-Dead"].Value,
				activesum = sv["Friend-S2-ActiveSum"].Value,
				called = sv["Friend-S2-Entered"].Value,
				dod = sv["Friend-S2-Dead"].Value + sv["Friend-S2-Depart"].Value
			},
			f1 = {
				oncall = sv["Friend-F1-Oncall"].Value,
				departed = sv["Friend-F1-Depart"].Value,
