				oncall = sv["Hostile-F1-Oncall"].Value,
				departed = sv["Hostile-F1-Depart"].Value,
				dead = sv["Hostile-F1-Dead"].Value,
				activesum = sv["Hostile-F1-ActiveSum"].Value,
				called = sv["Hostile-F1-Entered"].Value,
				dod = sv["Hostile-F1-Dead"].Value + sv["Hostile-F1-Depart"].Value
			},
			f2 = {
