				called = sv["Hostile-Bombers-Entered"].Value,
				dod = sv["Hostile-Bombers-Dead"].Value + sv["Hostile-Bombers-Depart"].Value
			}
		}

		--add all, do full written out version so reference lookup works
		ftbl.all = {
			oncall = ftbl.big.oncall + ftbl.small.oncall,
			departed = ftbl.big.departed + ftbl.small.departed,
			dead = ftbl.big.dead + ftbl.small.dead,
			activesum = ftbl.big.activesum + ftbl.small.activesum,
			called = ftbl.big.called + ftbl.small.called,
			dod = ftbl.big.dod + ftbl.small.dod
		}
		htbl.all = {
			oncall = htbl.big.oncall + htbl.small.oncall,
			departed = htbl.big.departed + htbl.small.departed,
			dead = htbl.big.dead + htbl.small.dead,
			activesum = htbl.big.activesum + htbl.small.activesum,
			called = htbl.big.called + htbl.small.called,
			dod = htbl.big.dod + htbl.small.dod
		}
		local boarding_tbl = {
