			bt_num_boarder_dod = sv["Boarder-Num-DoD"].Value,
			bt_num_boarding_wins = sv["Boarding-Num-Wins"].Value,
		}

		return {
			tv_f = ftbl, 
			tv_h = htbl, 
			tv_meta = {mission_over = sv["Mission-Is-Over"].Value},
			tv_boarding = boarding_tbl,
			tv_intel = {i_h_scanned = sv["Intel-H-Scanned-Total"].Value, i_h_tagged = sv["Intel-H-Tagged-Total"].Value}
		}

	end

	function GCW:VariableCacheUpdate(varname, new_val)

		local bs = self.battle_status
		if bs == nil then
			self:warning("Variable Cache Update function called before battle status table initiated!")
			return {}
		end

		if bs.cached_sxv_lua[varname] == nil then
			self.battle_status.cached_sxv_lua[varname] = {Value = new_val}
		else
			bs.cached_sxv_lua[varname].Value = new_val
		end

	end

	function GCW:UpdateVariable(varname, amount, override) --only adds to current value unless opt override set to true or string typ

		local current_var = mn.SEXPVariables[varname]
		if current_var == nil then
			GCW:warning("update variable function provided with invalid variable "..tostring(varname).."...\n")
			return
		end

		local new_val
		if override then
			new_val = amount
		else
			if type(amount) == "number" then
				new_val = current_var.Value + amount
			else
				new_val = amount
			end
		end
		mn.SEXPVariables[varname].Value = new_val

		self:VariableCacheUpdate(varname, new_val)

	end

