			--recall, if boarding target, the ship is a stripped down variant and cannot repair engines until mission is over
			repair_time_if_destroyed_func = function(ship_radius)
				ship_radius = ship_radius or 300
				local min_time = 50
				local max_time = 200
				local max_radius = 1500
				local m = (max_time-min_time)/max_radius
				--y = mx + b
				local repair_time =  min_time + (m * ship_radius)
				if repair_time > max_time then
					return max_time
				else
					return repair_time
				end
			end,
