		ai_meta = { --AI order sets and other things

			--order methods apply just to big ships
			--NAV_HELP 7832
			--         anytime  order  over
			--anywhere   4       3      -1
			--outside    2       1      -2

			--Case Study with possible incorrect retreat:
			--We have friendly f2 ships boarding hostile ships then departing as they complete boarding timing
			--  if we have team friendly allowed to retreat anywhere anytime, then as f2 ships complete their goals and depart.
			--The retreat threshold may trigger and tell the other f2 ships to leave early but
			--  this is not a true retreat, since the f2 ships are supposed to leave when they are done.
			--Thus, to avoid premature/incorrect retreats, we need to not check retreat until mission is over
			--  but we want to allow f2 ships to leave if they get damaged.
			--Fix can be made by ??

			retreat_method_anywhere_bigonly = -4, --only allow big ships to retreat if hurt anywhere, will not trigger early team retreat 
			retreat_method_outside_bigonly = -3, --only allow big ships to retreat if hurt once outside aoe zone, will not trigger early team retreat 

			retreat_method_outside_over = -2, --only retreat once the mission is marked as over and outside aoe zone
			retreat_method_anywhere_over = -1, --only retreat once the mission is marked as over
			retreat_method_outside_order = 1, --retreat if general retreat order given and outside aoe zone
			retreat_method_outside_anytime = 2, --retreat any time but only if outside aoe zone
			retreat_method_anywhere_order = 3, --retreat any where but only retreat if general retreat order given 
			retreat_method_anywhere_anytime = 4, --retreat any where and any time

			--order levels, recall we don't want to clear orders in case undocking or docking
			priority_max_before_ply = 88,  --Player orders have a priority of 90-100
			priority_min_from_ply =   90,
			priority_max_from_ply =   101,
			priority_ai_150 = 150,
			priority_ai_160 = 160,
			priority_ai_170 = 170,
			priority_ai_175 = 175,
			priority_ai_199 = 199, --allow undock to properly 
			priority_ai_200 = 200, --reserved only for undock

			small_AI_order_ids = {
				order_guard = 1,
				order_attack = 2,
				order_attack_any = 3,
				order_stay_near = 4
			},

			small_AI_default_guard = 1,
			small_AI_default_attack = 2,

			--boarding statuses
			boarding_status_1stalk = 1,
			boarding_status_2dock = 2,
			boarding_status_3windepart = 3, --only set if successfully boarded for long enough to get cargo and then un-docked

			big_AI_order_documentation = { --OVERVIEW, NOT ACTUAL TABLE! example below

				--all big ship orders use waypoints, 
					--specifically a waypoint order using their self waypoint, 
					--such as 'Vanguard 1' using waypoint path 'Vanguard 1-'
				--string variable is just list of building blocks

				order_overall_method = {    --returns ai-order
					--"" or nil
						--no order
					--"ai_depart_force"   
						--forces a warp out when done with waypoints
						--no options
					--"ai_depart_goal"    
						--orders a warp out when done with waypoints
						--no options
					--"ai_waypoint_once"  
						--orders 'do-waypoints-once'
						--options for 
							--<order_options_for_target> and <order_offset_method> 
								--1. get target ship waypoint or static waypoint, 
								--2. set self waypoint to that location + offset,
								--3. order 'do-waypoints-once' for self waypoint
					--"ai_waypoint_track" 
						--tracks waypoint with lua sexp, only difference of this with waypoint_once is that ship will move to orientation and keep following 
						--options for 
							--<order_options_for_target> and <order_offset_method> 
								--1. get waypoint of target ship or static waypoint, 
								--2. set the self waypoint to that position + offset and set Movements:Add_Waypoint_Track_Object()
								--3. use Movements:Add_Ship_Track_Waypoint() on self waypoint and self ship
				},

				order_options_for_target = { --returns list of targets, such as {self_team_f1}, {other_team_big}
					--"" or nil
						--no active target, but is open to taking new targets
					--"to_ship_self"
						--uses the ship self, sets actual target to self
					--"to_wp_self" 
						--uses the ship's self waypoint, such as 'Vanguard 1' using waypoint path 'Vanguard 1-', sets actual target to self waypoint
					--"to_wp_planet_center" 
						--will use waypoint "WP Planet Center", sets actual target to self
					--"to_wp_team_exitvector"
						--will use waypoint for team "", sets actual target to self
					--"to_wp_battle_center"
						--uses waypoint "WP Battle Center", sets actual target to self
					--<table, in form {"<team_id>", {"<subtype>"}, <index_in_list>, "<tol_target_is_ship or tol_target_is_waypoint>"}>
						--uses args to make into master list, then picks target from list, sets actual target to selected matching ship
							--[1] team -> "tol_other_team", "tol_same_team", "tol_dynamic_team" ; "tol_other_team" is default. Note, "tol_dynamic_team" will choose friendly if any other big friendly ships are present, also if using this option it is best to set the next option to "tol_all_but_my_f" or nil
							--[2] subtype -> f1, f2, f3 or any combination, or {"tol_all_but_my_f"} (which is default)
							--[3] index in list -> tol_i_last, tol_i_first, tol_i_strongest, tol_i_weakest, tol_i_match ; tol_i_match is default uses the get corresponding i index function and is default
							--[4] "tol_target_is_ship" or "tol_target_is_waypoint" -> "tol_target_is_waypoint" grabs the target ship's waypoint location instead of the ship location
				},

				order_offset_method = {   --returns vector, used for distance/offset of waypoint placement, default is no offset or same as {0, 0, 0}
					--"" or nil 
						--uses default specified above
					--"d_target_pursue" or "d_target_broadside"
						--uses the combined relative radii of this ship and target ship, if target is wp then uses just the ship radii
					--"d_into_inner_aoe_edge" or "d_into_inner_aoe_core"
						--moves forward set amount to either inner aoe radius*2
						--reinforcing ships may not want to block or move right into current friendly ships, so use reach exterior
						--attacking ships may want to move right into hostiles, so use reach interior
					--"d_planet_center"            
						--distance to the waypoint "WP Planet Center"
					--"d_battle_center"            
						--distance to the waypoint "WP Battle Center"
					--<vector, in form {0,0,0}>     
						--vector, ex, waypoint-once 10,000 in front of ship
						--useful to making all ships go a certain distance, as opposed to all ships trying to crow around one waypoint
				},

				order_rotation_type = { --returns string with type, used only for goals that have an end rotation
					--"" or nil
						--no rotation
					--<string, "r_relative_self" or "r_relative_target_actual" or "r_relative_target_ship" or "r_global">
					--global, relative to self ship or actual target (which could be waypoint) or the set target (which is what active ships table uses) 
				},

				order_rotation_pbh = { --returns table with pbh or string with special pbh override, used only for goals that have an end rotation
					--"" or nil
						--no rotation
					--<table, in form {p=, b=, h=} or string with special override> 
						--table form: p,b,h of rotation in degrees, is converted to radians in function.
						--string form: string with special pbh override from Movement scripts.
				},

				order_waypoint_cap = {  --returns number, has default of GCW.cv.waypoints_mission.default_cap_speed
					--"" or nil
						--uses default specified above
						--also using this variable can also do things like (GCW.cv.waypoints_mission.default_cap_speed * 0.40)
							--Also, reminder if make capped speed slower then shorten wp distance for escort missions
					--<value, in form of number> 
						--if 0 or negative then it will be auto set to -1, which removes any current waypoint cap speeds
					--<string, in form "wp_slow_when_unaligned"
						--if set as this string, ship will use the default waypoint speed as a max and a min of 1, 
						--and linearly pick a value with how aligned it is to target ship
						--is default value if no target ship
				},

				order_priority = {  --returns number, has default of GCW.cv.ai_meta.priority_ai_150 (150)
					--"" or nil
						--uses default specified above
					--<value, in form of string matching number> 
						--if 0 or negative then it will be set to 1
				}
			},

			go_nothing_default = { 
				order_overall_method = "ai_donothing_default",
				order_options_for_target = "to_ship_self",
				order_priority = "priority_ai_150"
			},

			go_nothing_clear_setself = {  
				order_overall_method = "ai_nothing_clear",
				order_options_for_target = "to_ship_self",
				order_priority = "priority_ai_150"
			},

			go_nothing_clear_setopen = {  
				order_overall_method = "ai_nothing_clear" ,
				order_options_for_target = "",
				order_priority = "priority_ai_150"
			},

			go_departhelper = {  --used only on exit into hyperspace, sets ship to self and prevents any new orders to allow :ForceWarpOut( to trigger
				order_overall_method = "ai_nothing_clear",
				order_options_for_target = "to_ship_self",
				order_priority = "priority_ai_199",
				order_waypoint_cap = GCW.objects.placement_values.wp_tabled_big_max_speed
			},

			go_retreathelper = {  --go toward waypoint then once away from AOE a depart is triggered
				order_overall_method = "ai_waypoint_once",
				order_options_for_target = "to_wp_team_exitvector",
				order_waypoints_done = "go_departgoal",
				order_priority = "priority_ai_175",
				order_waypoint_cap = GCW.objects.placement_values.wp_tabled_big_max_speed
			},

			go_departgoal = {  --depart via vector alignment
				order_overall_method = "ai_depart_goal",
				order_options_for_target = "to_ship_self",
				order_priority = "priority_ai_175",
