		mfunc__calculate_h_pool = {
			func_hpool_default = function (base_pool_size, ply_fac, hos_fac)

				local small, big = base_pool_size, base_pool_size
				local pool = base_pool_size

				if ply_fac == hos_fac then
					--player and hostile same faction
					return {h_small_pool = base_pool_size, h_big_pool = base_pool_size}

				elseif ply_fac == "r" then
					--player rebels
					if hos_fac == "e" then
						small = (pool * 1.4) + 1.0
						big = (pool * 1.25) + 0.75
					elseif hos_fac == "p" then
						small = (pool * 1.15) + 0.7
						big = (pool * 1.05) + 0.30
					end

				elseif ply_fac == "e" then
					--player empire
					--ensure hostile big does not get lower then 0.3, which is freighter size
					--that way things like escort attack missions can still happen 
					if hos_fac == "r" then
						small = (pool * 0.75) + 0.25
						big = (pool * 0.8) - 0.5
					elseif hos_fac == "p" then
						small = (pool * 0.80) + 0.20
						big = (pool * 0.9) - 0.4					
					end

				elseif ply_fac == "p" then
					--player pirates
					if hos_fac == "e" then
						small = (pool * 1.2) + 1.0
						big = (pool * 1.1) + 0.5
					elseif hos_fac == "r" then
						small = (pool * 0.85) + 0.5
						big = (pool * 0.95) + 0.1
					end

				end

				return {h_small_pool = small, h_big_pool = big}
			end
		},

