		mfunc__outcome_check = {
			func_outcome_default_1 = function()
				--recall outcome is calculated on debrief again to get correct string word, 
				--so keep that in mind when doing the above depart protocols
				--b/c those will affect dod numbers
				local l_is_mission_over = false
				local l_outcome_options = GCW.cv.outcome_options
				local l_outcome
				local trk_tbl = GCW:TrackerVariablesTable()
				local f = trk_tbl.tv_f
				local h = trk_tbl.tv_h

				--success or draw: all big hostiles gone and most or all of small hostiles
				--failure: all friendly gone but hostiles remain
				--NOTE: waved ships might not all arrive if their mothership dies before the next wave
				--for example, oncall is 8 ships (2 wings), mothership dies, so max dod is 4, which will never be > 8 required to trigger
				--recall that on mission start _1 these oncall variables for small ships do not count waves, thus...
				--..there might be times when there are still small ships flying around even though the dod amount is >= oncall, thus...
				--..always check the active sum too (only needed for small since oncall will always stay updated for large since they do not use waves)
				--do not need to use timer since we can win before all friendlies arrive and we can lose before all hostiles arrive

				local ply_only_smallf_left = false
				if ( f.small.dead >= (f.small.oncall-1) ) and f.small.activesum <= 1 then
					ply_only_smallf_left = true
				end

				--check if all hostiles dod/gone
				local all_hostiles_gone = (h.all.dod >= h.all.oncall and h.all.activesum <= 0)
				if all_hostiles_gone then
					--all hostiles gone...check about friendlies
					if f.big.oncall > 0 then
						--were friendly big ships, so go by that
						if f.big.dead >= f.big.oncall  then
							--all friendly big are dead
							l_outcome = l_outcome_options.mission_stalemate.id_key
						else
							--friendly big not all dead
							l_outcome = l_outcome_options.mission_success.id_key
						end
					else
						--no friendly big, so go by how many friendly small are left
						if ply_only_smallf_left then
							--only player left
							l_outcome = l_outcome_options.mission_stalemate.id_key
						else
							--some wingmen left
							l_outcome = l_outcome_options.mission_success.id_key
						end
					end

				else
					--if hostiles are still alive then only way mission is over is if it was a failure by having all friendly dod
					--since if hostiles still around, and friendly still around, fighting likely continues

					--recall imperial player won't get to do special bay depart in this case, 
					--  since mission usually won't end until all hostiles dead or all friendly big dead/departed 
					--  thus no big ships to depart to
					--  and big ships do not take play dock if they are leaving b/c of damage
					--what about off chance friendly team is ordered away?
					--  in theory the depart docking updater should catch this
					if ply_only_smallf_left and f.big.dod >= f.big.oncall then
						l_outcome = l_outcome_options.mission_failure.id_key
					end

					--failsafe check:
					--  mission known to be over, so this is running on m1 end
					--  have not found valid outcome yet for some reason
					--  and in this else block so 
					--  goal failed since hostiles survived
					if l_outcome == nil and (trk_tbl.tv_meta.mission_over == 1) then
						l_outcome = l_outcome_options.mission_failure.id_key
					end

				end

				if l_outcome ~= nil then
					l_is_mission_over = true
				end

				return {
					is_mission_over = l_is_mission_over,
					mission_outcome_key = l_outcome
				}

			end,

			func_outcome_defend_escort = function()
				local l_is_mission_over = false
				local l_outcome_options = GCW.cv.outcome_options
				local l_outcome
				local trk_tbl = GCW:TrackerVariablesTable()
				local f = trk_tbl.tv_f
				--local h = trk_tbl.tv_h

				--mission over when all friendly f1+f2 dead or departed

				--do special failsafe check:
				--  if mission is known over, so this is running on m1 end
				--  have not found valid outcome yet for some reason
				--  possibly due to things like imperial player docking and 
				--  dock update not catching b/c of some weird ship action edge case/timing
				local mission_set_as_over = (trk_tbl.tv_meta.mission_over == 1)

				if ((f.f1.dod + f.f2.dod) >= (f.f1.oncall + f.f2.oncall)) or mission_set_as_over then

					local percent_f_dead = ( (f.f1.dead + f.f2.dead) / (f.f1.oncall + f.f2.oncall) )

					if percent_f_dead >= 0.75 then
						l_outcome = l_outcome_options.mission_failure.id_key
					elseif percent_f_dead >= 0.25 then
						l_outcome = l_outcome_options.mission_stalemate.id_key
					else
						l_outcome = l_outcome_options.mission_success.id_key
					end

				end

				if l_outcome ~= nil then
					l_is_mission_over = true
				end

				return {
					is_mission_over = l_is_mission_over,
					mission_outcome_key = l_outcome
				}

			end,

			func_outcome_attack_escort = function()
				local l_is_mission_over = false
				local l_outcome_options = GCW.cv.outcome_options
				local l_outcome
				local trk_tbl = GCW:TrackerVariablesTable()
				local h = trk_tbl.tv_h
				--local f = trk_tbl.tv_f

				--mission over when all hostile f1+f2 dead or departed
				--no need to account for special case of imperial player bay-departing
				--since this core check only involves hostile ships

				--failsafe check (just for consistency sake):
				--  mission known to be over, so this is running on m1 end
				local mission_set_as_over = (trk_tbl.tv_meta.mission_over == 1)

				if ((h.f1.dod + h.f2.dod) >= (h.f1.oncall + h.f2.oncall)) or mission_set_as_over then

					local percent_h_dead = ( (h.f1.dead + h.f2.dead) / (h.f1.oncall + h.f2.oncall) )

					if percent_h_dead >= 0.75 then
						l_outcome = l_outcome_options.mission_success.id_key
					elseif percent_h_dead >= 0.25 then
						l_outcome = l_outcome_options.mission_stalemate.id_key
					else
						l_outcome = l_outcome_options.mission_failure.id_key
					end

				end

				if l_outcome ~= nil then
					l_is_mission_over = true
				end

				return {
					is_mission_over = l_is_mission_over,
					mission_outcome_key = l_outcome
				}

			end,

			func_outcome_recon_h_escort = function()
				local l_is_mission_over = false
				local l_outcome_options = GCW.cv.outcome_options
				local l_outcome
				local trk_tbl = GCW:TrackerVariablesTable()
				local h = trk_tbl.tv_h
				local h_scanned = trk_tbl.tv_intel.i_h_scanned
				local h_tagged = trk_tbl.tv_intel.i_h_tagged
				--local f = trk_tbl.tv_f

				--mission over when all hostile f1+f2 dead or departed or all hostile scanned and tags are out/all tagged
				--outcome based on how many tagged

				--NAV_HELP 8778
				--recall, number of tracking beacons recon starfighters can hold 
				--is 4 across the board

				--failsafe check (just for consistency sake):
				--  mission known to be over, so this is running on m1 end
				local mission_set_as_over = (trk_tbl.tv_meta.mission_over == 1)
				local total_big_f1f2f3 = h.f1.oncall + h.f2.oncall + h.f3.oncall

				-- I. if h big oncall <= 0 -> over
				--II. if h big oncall > 0
				--  1. if hostile big all dod -> over
				--  2. if hostile big active 
				--      A. -scanned all
				--          -tag out -> over
				--          -tagged >= 4 (same as out) -> over
				--          -tagged < 4 and not out of tags
				--            -tagged >= big h oncall -> over
				--            -tagged < big h oncall (not over) there are still active hostile big and they have not all been tagged
				--      B. -scanned some -> not over (regardless of tag, b/c still some to scan)

				local recon_mission_over = mission_set_as_over
				if not recon_mission_over then

					--cache how many beacons player has left
					local ply_tags_left = 0
					local ply = FotG:GetPlayerShip()
					if ply ~= nil and ply:isValid() and ply:getBreedName() == "Ship" then
						local ply_secondaries = ply.SecondaryBanks
						if ply_secondaries ~= nil and ply_secondaries:isValid() and #ply_secondaries == 1 then
							local tag_wep = ply_secondaries[1]
							if tag_wep ~= nil then
								if tag_wep.WeaponClass.Name == "XX-23 Homing Beacon" then
									ply_tags_left = tag_wep.AmmoLeft
								end
							end
						end
					end

					--check logic
					if total_big_f1f2f3 <= 0 then --I.
						recon_mission_over = true
					else --II.
						if (h.f1.dod + h.f2.dod) >= (total_big_f1f2f3) then --1.
							recon_mission_over = true
						else --2.
							if h_scanned >= total_big_f1f2f3 then --A.
								if ply_tags_left <= 0 or h_tagged >= 4 then
									recon_mission_over = true
								else
									if h_tagged >= total_big_f1f2f3 then
										recon_mission_over = true
									else
										recon_mission_over = false
									end
								end
							else --B.
								recon_mission_over = false
							end
						end
					end
				end

				if recon_mission_over or mission_set_as_over then

					if total_big_f1f2f3 <= 0 then 
						--no hostiles to tag, failsafe
						l_outcome = l_outcome_options.mission_success.id_key
					elseif total_big_f1f2f3 <= 3 then 
						--3 or fewer og hostiles to tag
						if (h_tagged >= 2 and h_scanned >= 1) or (h_tagged == 1 and total_big_f1f2f3 == 1) then
							l_outcome = l_outcome_options.mission_success.id_key
						elseif h_tagged >= 1 and total_big_f1f2f3 > 1 then
							l_outcome = l_outcome_options.mission_stalemate.id_key
						else
							l_outcome = l_outcome_options.mission_failure.id_key
						end
					else
						--four or more og hostiles to tag
						if h_tagged >= 3 and h_scanned >= 3 then
							l_outcome = l_outcome_options.mission_success.id_key
						elseif h_tagged >= 1 then
							l_outcome = l_outcome_options.mission_stalemate.id_key
						else
							l_outcome = l_outcome_options.mission_failure.id_key
						end
					end 

				end

				if l_outcome ~= nil then
					l_is_mission_over = true
				end

				return {
					is_mission_over = l_is_mission_over,
					mission_outcome_key = l_outcome,
					soft_voice_failure = true
				}

			end,

			func_outcome_board_hostile = function()
				local l_is_mission_over = false
				local l_outcome_options = GCW.cv.outcome_options
				local l_outcome
				local trk_tbl = GCW:TrackerVariablesTable()
				--local f = trk_tbl.tv_f
				--local h = trk_tbl.tv_h
				local boarding = trk_tbl.tv_boarding

				--if all boarders DoD then over (nothing left to do)

				--NAV_HELP 4433, the following is accounted for in the extra helper function
				--if all hostile boardables are DoD will still might need to protect our friendly boarders
				--  so we need to order our friendly boarders to leave, but keep the rest of us around to protect them
				--  this includes boarders which are likely already leaving if they are still around

				local sum_boarder_oncall = boarding.bt_num_boarder_oncall
				local sum_boarder_dod = boarding.bt_num_boarder_dod
				local sum_boarding_wins = boarding.bt_num_boarding_wins

				local sum_boardable_oncall = boarding.bt_num_boardable_oncall
				--local sum_boardable_dod = boarding.bt_num_boardable_dod

				--do special failsafe check:
				--  if mission is known over, so this is running on m1 end
				--  have not found valid outcome yet for some reason
				--  possibly due to things like imperial player docking and 
				--  dock update not catching b/c of some weird ship action edge case/timing
				local mission_set_as_over = (trk_tbl.tv_meta.mission_over == 1)

				if (sum_boarder_dod >= sum_boarder_oncall) or mission_set_as_over then

					--NAV_HELP 8777
					--need at least 1 boarding win for a successful mission
					--get ratio of boarding wins to boardable_oncall (ie the boardable_possible)
					local percent_boarded_successful = (sum_boarding_wins/sum_boardable_oncall)

					if percent_boarded_successful >= 0.75 then
						l_outcome = l_outcome_options.mission_success.id_key
					elseif percent_boarded_successful > 0 then
						l_outcome = l_outcome_options.mission_stalemate.id_key
					else
						l_outcome = l_outcome_options.mission_failure.id_key
					end

				end

				if l_outcome ~= nil then
					l_is_mission_over = true
				end

				return {
					is_mission_over = l_is_mission_over,
					mission_outcome_key = l_outcome
				}

			end,

		},

		mfunc__extra_helper = { --returns true if ran fully, false otherwise. If returns true will not run again
			func_extrahelp_none = function()
				--do nothing
				return true
			end
		},

		mfunc__run_when_all_h_dod = {
			func_all_h_dod_none = function()
				--do nothing
			end,

			func_all_h_dod_escort = function()
				--escort leave earlier
				--  get all friendly ships order type 
				--  if wp once then move wp if too far
				--  recall all ships are following their own waypoints
				local b_as = GCW.battle_status.active_ships.Friendly.big
				local wp_info = GCW.cv.waypoints_mission 
				local new_dist_to_wp = 700
				for _,v_as in ipairs(b_as) do
					if string.equalAny(v_as.as_self_aigoal_id, {"go_highway_long", "go_highway_medium", "go_highway_short"}) then
						local ship = mn.Ships[v_as.as_self_name]
						local wp_name = v_as.as_self_name .. wp_info.path_bigship_suffix
						local wp_path = mn.WaypointLists[wp_name]
						if ship ~= nil and ship:isValid() and wp_path ~= nil and wp_path:isValid() then 
							local wp_1 = wp_path[1]
							local ship_pos = ship.Position
							if wp_1 ~= nil and wp_1:isValid() and (ship_pos:getDistance(wp_1.Position) > (new_dist_to_wp * 1.1)) then
								wp_1.Position = ship_pos + ship.Orientation:unrotateVector(ba.createVector(0, 0, new_dist_to_wp))
							end
						end
					end
				end
				--could have unlikely edge case where other friendlies are still blocking these ships from reaching wp and ending mission
				--so update fail safe mission time
				GCW.battle_status.all_h_dod_failsafe_mtime = mn.getMissionTime() + 120 
				--at this point code will simply run final orders
				--engines will still be checked to allow warping ofc
			end
		}

	}

