	GCW.data = {} --add any GCW tables that record dynamic information here, ultimately this data table is saved in the json
	--Dynamically updated means only values within already existing cells are changed, new cells are not added or subtracted
	GCW.data.ships = {} --gets dynamically updated during game-play
	GCW.data.wings = {} --changes during mission choice section
	GCW.data.player = {} --gets dynamically updated during game-play and when the mission generator is run
	GCW.data.map_progress = {} --gets dynamically updated on accept mission
	GCW.data.backlog_ships = {} --gets dynamically updated on accept mission

	GCW.responses_table = {} --for m_intro and mission choice

	function GCW:warning(extra_info, bad_error) --search for "GCW Warning: " in debug log (the errors will give pop-ups)

		extra_info = tostring(extra_info) or ""

		if bad_error then
			warning("GCW Error: "..extra_info.."! Please inform wookieejedi that this error appeared, because it means something did not work correctly. \n")
		else
			print("GCW Warning: "..extra_info.." \n")
		end

	end

	function GCW:TeamHelper(teamname)

		teamname = string.filterInvisible(teamname) --to ensure Friendly#Healer and other similar names are properly read

		if teamname == "Friendly" then
			return "Friendly"
		else --deals with Hostile and Pacified and other non-friendly team names
			return "Hostile"
		end

	end

	function GCW:Responses_Reset() --resets all responses that are stored in the global table

		self.responses_table = nil
		self.responses_table = {
			choices_are_on = false,
			most_recent_key_press = "",
			is_help_on = true,
			are_all_valid = false,
			are_choices_done = false,
			screen_fade_time = 1.8,
			choices_done_timestamp = -1,
			response_type_key = "choices_list_M_Intro",
			ui_tracking = {},
			absolute_max_choices = 20,
			choices_list_M_Intro = {}, -- set in InitiateIntroOptions()
			choices_list_M_0 = {}, --this is initiated separately at OnStart_m_0() since it is dynamic,
			choices_list_M_Final1 = {}
		}

		--print("GCW: Successfully set choices to default values...\n")

	end

	function GCW:Responses_GetChoiceKey(choice_i_id)

		return "ui_item_Choice_" .. choice_i_id

	end

	function GCW:Responses_Hover_Reset()

		if not self.responses_table.choices_are_on then return end

		self.responses_table.ui_tracking.ui_hover_active = false
		self.responses_table.ui_tracking.ui_hover_checknoise = true

		self.responses_table.ui_tracking.ui_hover_z = -1
		self.responses_table.ui_tracking.ui_hover_i = 0
		self.responses_table.ui_tracking.ui_hover_group = ""

	end

	function GCW:Responses_Hover_Deregister()

		if not self.responses_table.choices_are_on then return end

		self.responses_table.ui_tracking.ui_hover_active = false

	end

	function GCW:Responses_Hover_Register(ui_item_key, i_level)

		if not self.responses_table.choices_are_on then return end

		--registering we are hovering over an element
		local rui = self.responses_table.ui_tracking

		local item_z = rui[ui_item_key].z_layer_level

		if item_z < rui.ui_hover_z then
			return
		end

		self.responses_table.ui_tracking.ui_hover_active = true 
		--keep out of if check, since hover may be same key and level as before
		--IE if hover over planet 1, then move mouse away and then hover over planet 1 again
		--  we still want the noise to play when hovering starts

		if rui.ui_hover_group ~= ui_item_key or rui.ui_hover_i ~= i_level then
			self.responses_table.ui_tracking.ui_hover_group = ui_item_key
			self.responses_table.ui_tracking.ui_hover_i = i_level
			self.responses_table.ui_tracking.ui_hover_z = item_z
			self.responses_table.ui_tracking.ui_hover_checknoise = true
		end

	end

	function GCW:Responses_Hover_CheckRun()

		if not self.responses_table.choices_are_on then return end

		--see if hover noise needs to play
		local rui = self.responses_table.ui_tracking

		if not rui.ui_hover_active then
			if not rui.ui_hover_checknoise then
				self:Responses_Hover_Reset()
			end
			return
		end

		--at this point we know hover is active so run protocols
		if rui.ui_hover_checknoise then
			FotG:PlaySound_Interface(FotG.sound_index_hover)
			self.responses_table.ui_tracking.ui_hover_checknoise = false
		end

		--recall hover active boolean gets set to false at start of draw loop

	end

	function GCW:Responses_Click_Reset()

		if not self.responses_table.choices_are_on then return end

		self.responses_table.ui_tracking.ui_click_active = false
		self.responses_table.ui_tracking.ui_click_invalidate = false
		self.responses_table.ui_tracking.ui_click_i = 0
		self.responses_table.ui_tracking.ui_click_group = ""
		self.responses_table.ui_tracking.ui_click_z = -1
		self.responses_table.ui_tracking.ui_click_extra = ""

	end

	function GCW:Responses_Click_Deregister()

		if not self.responses_table.choices_are_on then return end

		self.responses_table.ui_tracking.ui_click_active = false

	end

	function GCW:Responses_Click_Register(ui_item_key, i_level, invalidate_click, extra_info)

		if not self.responses_table.choices_are_on then return end

		--registering we clicked an element
		local rui = self.responses_table.ui_tracking

		local item_z = rui[ui_item_key].z_layer_level

		if item_z < rui.ui_click_z then
			return
		end

		self.responses_table.ui_tracking.ui_click_active = true

		extra_info = extra_info or ""
		if invalidate_click == nil then
			invalidate_click = false
		end

		if rui.ui_click_group ~= ui_item_key or rui.ui_click_i ~= i_level or rui.ui_click_invalidate ~= invalidate_click or rui.ui_click_extra ~= extra_info then
			self.responses_table.ui_tracking.ui_click_group = ui_item_key
			self.responses_table.ui_tracking.ui_click_i = i_level
			self.responses_table.ui_tracking.ui_click_invalidate = invalidate_click
			self.responses_table.ui_tracking.ui_click_z = item_z
			self.responses_table.ui_tracking.ui_click_extra = extra_info
		end

	end

	function GCW:Responses_Click_CheckRun()

		if not self.responses_table.choices_are_on then return end

		--see if click needs to run
		local rui = self.responses_table.ui_tracking

		if not rui.ui_click_active then 
			return
		end

		--click is valid so run protocols
		Script_State:UpdateMousePressed(true)

		local invalidate_click = rui.ui_click_invalidate
		local select_key = rui.ui_click_group
		local i_level = rui.ui_click_i

		if invalidate_click then
			--invalid so just play noise
			FotG:PlaySound_Interface(FotG.sound_index_fail)

		elseif rui[select_key].can_select_item then
			--valid so update values
			FotG:PlaySound_Interface(FotG.sound_index_click)

			self.responses_table.ui_tracking[select_key].active_i_lvl = i_level

			--extra if galaxy map 
			if select_key == "ui_item_Galaxy" then
				self.responses_table.ui_tracking.ui_item_Galaxy.key_in_planet_table = rui.ui_click_extra
			end

			--extra if exit
			if select_key == "ui_item_Exit" then
				if i_level == 1 then
					self:Responses_ExitNoSubmit()
				elseif i_level == 2 then
					self:Responses_ExitSubmit()
				end
			end

			--run if this hooks into actual choices list which is shown in the Summary UI
			local i_hook = rui[select_key].index_in_summary_table
			if i_hook ~= nil and i_hook > 0 then
				local response_type = self.responses_table.response_type_key
				self.responses_table[response_type][i_hook].opt_selection = self.responses_table[response_type][i_hook].opt_list[i_level]

				if i_hook == 1 and response_type == "choices_list_M_0" then
					self:SetPlanetUI_fromSelection()
				end
			end
		end

		--clear out save info so we can click again
		self:Responses_Click_Reset()

	end

	function GCW:Responses_UISetup() --builds UI tracker for current 'choices type', requires that give 'choices type' already was initiated/populated

		--use full paths so auto lookup works
		local full_choices_tbl = self.responses_table[self.responses_table.response_type_key]

		--hovers are global and do not have full reset function 
		--b/c hover need to run continually
		--b/c can only have one hover at a time and they could be anything
		self:Responses_Hover_Reset()

		self:Responses_Click_Reset()

		self.responses_table.ui_tracking.ui_helper_summary_y = 0 --for aligning choices to summary level

		self.responses_table.ui_tracking.main_input_enabled = true

		--UI element for Summary of choices
		self.responses_table.ui_tracking.ui_item_Summary = {
			can_select_item = true,
			max_i_lvl = #full_choices_tbl,
			active_i_lvl = 0, 
			index_in_summary_table = -1,
			key_in_planet_table = "",
			show_typing_cursor = false,
			z_layer_level = 1
		}

		--UI element for exit/submit
		self.responses_table.ui_tracking.ui_item_Exit = {
			can_select_item = true,
			max_i_lvl = 2,
			active_i_lvl = 0, 
			index_in_summary_table = -1,
			key_in_planet_table = "",
			show_typing_cursor = false,
			z_layer_level = 3
		}

		--UI element for options for a choice 
		for i,v_choiceentry in ipairs(full_choices_tbl) do
			local ui_name = self:Responses_GetChoiceKey(i)
			local selectable = (v_choiceentry.opt_input_type == self.cv.input_type.typ_list) 
			local show_typing = (v_choiceentry.opt_input_type == self.cv.input_type.typ_number or v_choiceentry.opt_input_type == self.cv.input_type.typ_string)
			self.responses_table.ui_tracking[ui_name] = {
				can_select_item = selectable,
				max_i_lvl = #v_choiceentry.opt_list, 
				active_i_lvl = 0, 
				index_in_summary_table = i,
				key_in_planet_table = "",
				show_typing_cursor = show_typing,
				z_layer_level = 2 --only one choice options UI can be shown at a time so having all same z is fine
			}
		end

		--UI element for galaxy map
		self.responses_table.ui_tracking.ui_item_Galaxy = {
			can_select_item = true,
			max_i_lvl = self.cv.base_filenames.galaxy_plt_image_count,
			active_i_lvl = 0, 
			index_in_summary_table = -1,
			key_in_planet_table = "",
			show_typing_cursor = false,
			z_layer_level = 0
		}

	end

	function GCW:tc(tbl_or_, select_option)

		--tc is table choose function that takes an argument,..
		--..checks if it is a table and chooses a random value from that table if it is..
		--..If the value is not a table it returns that value..
		--..Optional 'select option' that can be set to "range" to select from a range of two values, or "random" which is the default.
		select_option = select_option or "random"
		local final = tbl_or_
		if type(tbl_or_) == "table" then
			local n = #tbl_or_
			if n > 0 then
				if n == 1 then
					final = tbl_or_[1]
				end
				if n > 1 then
					if select_option == "range" and n >=2 then
						local low = math.MM_iTable(tbl_or_,"min")
						local high = math.MM_iTable(tbl_or_,"max")
						final = ba.rand32(low, high)
					else --ie select_option == "random" or nil
						local num = ba.rand32(1, n)
						final = tbl_or_[num]
					end
				end
			end
		end

		return final

	end

	function GCW:tget(m_type, key_list, tc_option)

		--tested with nested mts and various options
		local missions = self.mission.single_types
		m_type = m_type or "mt_default"
		tc_option = tc_option or "full"
		--if this mission type doesn't exist then just use default template
		local mission_table = missions[m_type]
		if mission_table == nil then
			self:warning("mission type <"..tostring(m_type).."> not present in mission types table, using mtype <default>...\n")
			mission_table = missions.default
		end
		--set the meta table, or if there is none, use default
		local mission_metatable_name = mission_table.mission_meta.mtype_metatable
		if mission_metatable_name == nil then
			self:warning("meta table not specified from mission type <"..tostring(m_type)..">, using mtype <default>...\n")
			mission_metatable_name = "mt_default"
		end

		--compile variable
		local keyn = #key_list
		if keyn <= 0 or type(key_list) ~= "table" then
			self:warning("no keys listed for function or not type table, returning value of 1. ...\n")
			return 1
		end

		local k = key_list
		local i = #k
		local t 

		if i > 8 then 
			self:warning("more than 8 keys are listed in this key table, update the tget function! ...\n")
		end

		--print("For mission type '"..m_type.."' key_list is ("..table.concat(key_list, ", ").."). Number of keys is "..tostring(i)..". \n")

		--find key without resetting tables
			--recall t = {true}
			--cannot check t.true[1] without error, so only check if that key is for sure going to be in that order and valid

		if mission_table[k[1]] ~= nil then
			if i == 1 then
				t = mission_table[k[1]]
			elseif mission_table[k[1]][k[2]] ~= nil then
				if i == 2 then
					t = mission_table[k[1]][k[2]]
				elseif mission_table[k[1]][k[2]][k[3]] ~= nil then
					if i == 3 then
						t = mission_table[k[1]][k[2]][k[3]]
					elseif mission_table[k[1]][k[2]][k[3]][k[4]] ~= nil then
						if i == 4 then
							t = mission_table[k[1]][k[2]][k[3]][k[4]]
						elseif mission_table[k[1]][k[2]][k[3]][k[4]][k[5]] ~= nil then
							if i == 5 then
								t = mission_table[k[1]][k[2]][k[3]][k[4]][k[5]]
							elseif mission_table[k[1]][k[2]][k[3]][k[4]][k[5]][k[6]] ~= nil then
								if i == 6 then
									t = mission_table[k[1]][k[2]][k[3]][k[4]][k[5]][k[6]] 
								elseif mission_table[k[1]][k[2]][k[3]][k[4]][k[5]][k[6]][k[7]] ~= nil then
									if i == 7 then
										t = mission_table[k[1]][k[2]][k[3]][k[4]][k[5]][k[6]][k[7]]
									elseif mission_table[k[1]][k[2]][k[3]][k[4]][k[5]][k[6]][k[7]][k[8]] ~= nil then
										if i == 8 then
											t = mission_table[k[1]][k[2]][k[3]][k[4]][k[5]][k[6]][k[7]][k[8]]
										end
									end
								end
							end
						end
					end
				end
			end
		end

		--if that key did not work try using key in meta table
		if t == nil then
			if m_type == "mt_default" then
				--print error if on default already and key is nil
				self:warning("key-list input of ("..table.concat(key_list, ", ")..") cannot be found in any mission type tables, including the default type. Returning value of 1. ...\n")
				t = 1
			else
				--if that key did not work then use meta table
				--print("running recursion for mission type "..tostring(m_type).." with now running "..mission_metatable_name.."..\n")
				t = self:tget(mission_metatable_name, key_list, tc_option)
			end
		end

		local final
		--run tc_options, if "full" then keep as is

		--print("--Current t value is "..tostring(t)..". For mission type '"..m_type.."' key_list is ("..table.concat(key_list, ", ").."). Number of keys is "..tostring(i)..". \n")

		--recall if we run this recursively with table choice options then they will get ran twice or more..
		--..within the recursion then once at the final out, so only run if there is a table

		if type(t) == "table" then
			if tc_option == "random" or tc_option == "range" then
				final = self:tc(t,tc_option)
			elseif tc_option == "random_weighted" then
				final = math.Random_Weighted(t)
			end
		end

		if final == nil then 
			final = t 
		end

		return final

	end

	function GCW:opteam(team)

		if team == "Friendly" then
			return "Hostile"
		else
			return "Friendly"
		end

	end

	function GCW:GetFactionfromTeam(team)

		if team == "Friendly" then
			return self.data.player.faction
		else
			return self.data.player.mission_hostile_faction
		end

	end

	function GCW:EraNum() --returns era number of ply tbl

		return tonumber(self.data.player.movie_era) or 1 --should get 1, 2, or 3

	end

	function GCW:GetEraPoolCap(optional_pfac)

		local era_max_info = self.cv.poolsize_era_limits[self:EraNum()]
		local pfac = optional_pfac or self.data.player.faction
		local era_max_value = era_max_info[pfac]
		if era_max_value == nil then
			print("GCW Warning: era max value is nil, as it was trying to lookup pfac of "..tostring(pfac).." - era caps will not be used! \n")
		end

		return era_max_value

	end

	function GCW:FactionsIList()

		local t = {}
		for _,v in pairs(self.cv.factions) do
			table.insert(t, v)
		end
		return t

	end

	function GCW:Get_Frame_Key(team, faction, ply_fac)

		local p_fac = ply_fac or self.data.player.faction
		if p_fac == faction and team == "Hostile" then
			return "same_facs_as_ply"
		else
			return "ply_and_non_same_facs"
		end

	end

	function GCW:GetSkyboxKeyName()

		local skyboxes = self.cv.skybox_bg_details

		local ply = self.data.player
		local m_pinfo = self.planets[ply.mission_location]

		local xscale = ply.mission_bg_xscale or self:tget(ply.mission_type, {"mission_meta", "planet_zoom"}, "range")

		--if asteroid or debris
		if m_pinfo ~= nil and m_pinfo.objectfield_info ~= nil then
			local field_defaults = self.cv.objectfield_defaults
			local genre_id = m_pinfo.objectfield_info.field_genre
			if genre_id == field_defaults.field_type_debris then
				--debris
				return "skybox_debris"
			elseif genre_id == field_defaults.field_type_asteroid or genre_id == nil then
				--asteroids
				--get correct color or combo
				local asteroid_objs_meta = field_defaults.field_objects.genre_asteroid
				local asteroid_colors = m_pinfo.objectfield_info.field_objects or {asteroid_objs_meta.color_brown.field_obj_id}
				local asteroid_color_key = asteroid_colors[1] --there should only be 1 entry since the list is only 1 long
				local sb_asteroid
				for _,v_obj in pairs(asteroid_objs_meta) do
					if v_obj.field_obj_id == asteroid_color_key then
						sb_asteroid = v_obj.field_skybox_name
						break
					end
				end
				return sb_asteroid
			end
		elseif m_pinfo ~= nil and m_pinfo.nebula_info ~= nil then
			return "skybox_nebula"
		elseif xscale >= skyboxes.bg_scale_bigest then
			--planet closeup
			return "skybox_planet"
		else
			--default starfield
			return "skybox_starfield"
		end

	end

	function GCW:Battle_SetBigHPHelper(team, shipname, hp_value)

		--NAV_HELP 7894
		--battle_points * hp fraction (0-1.0)

		local bs = self.battle_status
		if bs == nil then return end

		local bs_team = bs[team]
		if bs_team == nil then return end

		bs_team.big_ship_strengths[shipname] = hp_value

	end

	function GCW:Battle_SumBigHPHelper(team) 

		--NAV_HELP 7894
		--battle_points * hp fraction (0-1.0)

		local bs = self.battle_status
		if bs == nil then return 0 end

		local bs_team = bs[team]
		if bs_team == nil then return 0 end

		local sum = 0
		for _,v_bp in pairs(bs_team.big_ship_strengths) do --list using ship names as keys
			sum = sum + v_bp
		end

		return sum

	end

	function GCW:Sort_ShipnameList(shipname_tbl)

		--use this function to sort ship names b/c
		--ship lists that go above 9 cannot be sorted with regular table.sort
		--b/c {"Van 3", "Van 11", "Van 1"} -> sorted becomes "Van 1", "Van 11", "Van 3"
		--where it should be "Van 1", "Van 3", "Van 11"

		--useful for shortened ship lists or non consecutive ones

		local sort_tbl = {}

		if #shipname_tbl < 1 then 
			return {} 
		end

		local tune_val_a = "000"
		local tune_val_b = "00"
		local space = " "

		--get position of last space
		--add text helper in name to allow for proper sorting
		for i,v in ipairs(shipname_tbl) do
			local tuned_name = v
			local first_space_i = string.find(v, space)
			local after_first_space = string.sub(v, first_space_i + 1)
			local second_space_i = string.find(after_first_space, space)
			if second_space_i == nil then
				--form "Vanguard 1" or "Red A"
				local num = tonumber(after_first_space)
				if type(num) == "number" then
					if num <= 9 then
					--form "Vanguard 1"
						tuned_name = string.gsub(v, space, tune_val_a)
					else
						--form "Vanguard 11"
						tuned_name = string.gsub(v, space, tune_val_b)
					end
				else
					--form "Red A"
					tuned_name = v
				end
			else 
				--form "Red A 1"
				tuned_name = v
			end

			sort_tbl[i] = tuned_name
		end

		--sort numbers
		table.sort(sort_tbl)

		--remove sorting helper text
		for i,v in ipairs(sort_tbl) do
		if string.find(v, tune_val_a) then
			sort_tbl[i] = string.gsub(v, tune_val_a, space)
		elseif string.find(v, tune_val_b) then
			sort_tbl[i] = string.gsub(v, tune_val_b, space)
			end
		end

		return sort_tbl

	end

	function GCW:AI_Pick_Next_Mission(mission_options_tbl, match_location, finale_possible)

		--do our best to pick a different mission type then last time
		--that way those folks who chose not to select the next mission and have it auto choose don't get bored

		local ply = self.data.player
		local previous_mtype = ply.mission_type
		local previous_mloc = ply.mission_location

		--recall the on intro start function made sure there were mission types for each loc
		local loc_mtype_options = {}
		if match_location ~= nil and self.planets[match_location] ~= nil then
			loc_mtype_options = {}
			for _,v in ipairs(mission_options_tbl) do
				if v.listed_mlocation == match_location then
					--copy over table exactly so keys match
					table.insert(loc_mtype_options, {listed_mtype = v.listed_mtype, listed_mlocation = v.listed_mlocation, listed_hostile_fac = v.listed_hostile_fac, listed_preferred_choice = v.listed_preferred_choice})
				end
			end
		else
			loc_mtype_options = mission_options_tbl
		end

		--go through mission options and i keys of ones with preference, if any
		local preference_i_list = {}
		local pref_count = 0
		for i_idx, v_info in ipairs(loc_mtype_options) do
			if v_info.listed_preferred_choice then
				pref_count = pref_count + 1
				preference_i_list[pref_count] = i_idx
			end
		end

		local num_choices = #loc_mtype_options

		--by default choose combo from entire list randomly
		--some randomness for regular missions gives variety
		--ie, for conquest mode, defending/escort missions are useful to build up forces
		--even if we are not always attacking
		local i_choice = ba.rand32(1, num_choices)

		--choose from preferred mission choice, if possible
		local use_preference_list = (finale_possible or ba.rand32(1,5) ~= 1) 
		if use_preference_list and pref_count > 0 then
			--choose combo from top preferences
			local idx_to_prefer_list = ba.rand32(1, pref_count)
			i_choice = preference_i_list[idx_to_prefer_list]
		end

		--go through list to see what mission types we can choose, 
		--grab first one we come across that is not a repeat if one exists
		--while accounting for if we only want to look at preference missions
		for i_id,v_info in ipairs(loc_mtype_options) do
			--if we have not done this mission type yet then choose this one and stop the loop
			if (previous_mtype ~= v_info.listed_mtype) and (previous_mloc ~= v_info.listed_mlocation) then
				--note that forcing a choice to a specific location makes options be limited to that location
				--and if previous mission was there then we will not reach this part of the repeat check
				--so repeat check mostly only used when next mission does not matter that much
				if use_preference_list then
					--if using preferred list then any preferred missions should be good
					if v_info.listed_preferred_choice then
						i_choice = i_id
						break
					end
				else
					i_choice = i_id
					break
				end
				--recall that if we don't find a non-repeat then i_choice still has it's default value
			end
		end

		local next_location = loc_mtype_options[i_choice].listed_mlocation
		local next_mtype = loc_mtype_options[i_choice].listed_mtype
		local next_hostile_fac = loc_mtype_options[i_choice].listed_hostile_fac

		return {ai_selected_mlocation = next_location, ai_selected_mtype = next_mtype, ai_selected_hos_fac = next_hostile_fac}

	end

	function GCW:IsSameAllegiance(alleg_score, team)

		-- (+) is Friendly
		-- (-) is Hostile
		if (team == "Friendly" and alleg_score > 0) or (team == "Hostile" and alleg_score < 0) then 
			return true
		else
			return false
		end

	end

	function GCW:SystemMatchesAllegianceType(sys_name, match_method, sys_score)

		sys_score = sys_score or self.data.map_progress[sys_name].allegiance_score_current

		if match_method == "Hostile" then 
			return (sys_score < 0)
		elseif match_method == "Neutral" then
			return (sys_score == 0)
		elseif match_method == "NonNeutral" then
			return (sys_score ~= 0)
		elseif match_method == "NonFriendly" then 
			return (sys_score <= 0)
		elseif match_method == "NonHostile" then 
			return (sys_score >= 0)
		elseif match_method == "Friendly" then
			return (sys_score > 0)
		elseif match_method == "All_Systems" then
			return true
		else
			return true
		end

	end

	function GCW:GetSystemsTbl(match_method) --default is all systems

		local systems = {}
		match_method = match_method or "All_Systems"
		local i = 1
		for k_sysname, v_sysinfo in pairs(self.data.map_progress) do
			if self:SystemMatchesAllegianceType(k_sysname, match_method, v_sysinfo.allegiance_score_current) then
				systems[i] = k_sysname
				i = i + 1
			end
		end

		return systems

	end

	function GCW:GetJSONFilename(with_ext)

		local pfac = self:GetPFac_from_Campaign()
		local filename = FotG:Get_PilotName_withPrefix(self.cv.base_filenames.jsonfile_prefix[pfac])
		if with_ext then
			--do not actually save as a json  b/c then FSO gets confused and thinks all json files are pilot files
			filename = filename .. ".txt"
		end
		return filename

	end

	function GCW:Is_GCW_Name(missionname)

		local answer = false
		if missionname ~= nil then
			if string.find(missionname, self.cv.base_filenames.core) ~= nil then
				answer = true
			end
		end
		return answer

	end

	function GCW:PathfinderAI(method_goal)

		--A-Star is a pathway to many abilities some consider to be... unnatural.

		ASTAR:clear_cached_paths()

		--convert to i-key
		local Gmap = {}
		for k,v in pairs(self.data.map_progress) do
			local conns_tbl = self:GetConnectedPlanetList(k, false)
			table.insert(Gmap, {sys_name=k, sys_allegiance=v.allegiance_score_current, sys_connections=conns_tbl})
		end

		local function Get_node_ikey_from_name(sys_name)
			local i_loc
			for i,v in ipairs(Gmap) do
				if v.sys_name == sys_name then
					i_loc = i
					break
				end
			end
			return i_loc
		end

		local function Is_valid_node(node, neighbor)
			return string.equalAny(node.sys_name, neighbor.sys_connections) 
		end

		local function Is_node_hostile(node)
			return node.sys_allegiance <= 0
		end

		local ply = self.data.player
		local p_loc = ply.mission_location
		local start_node = Gmap[Get_node_ikey_from_name(p_loc)]
		local default_path = {sys_name=p_loc}
		local path

		if method_goal == "go_to_hostile_commander" then
			local estimated_hostile_comm_loc = ply.commanders_info.Hostile.leader_location_guess
			local end_node = Gmap[Get_node_ikey_from_name(estimated_hostile_comm_loc)]
			if estimated_hostile_comm_loc ~= ply.mission_location then
				path = ASTAR:path(Gmap, start_node, end_node, Is_valid_node, true)
			else
				path = default_path
			end
		end

		if method_goal == "go_to_next_closest_hostile" then
			local num_non_friendly = #self:GetSystemsTbl("NonFriendly")
			if num_non_friendly > 0 then
				path = ASTAR:path(Gmap, start_node, Is_node_hostile, Is_valid_node, true)
			else
				path = default_path
			end
		end

		--now that we have the path, take the second one in path if i >= 2, otherwise just take first
		local next_chose_location_name
		if not path then
			print ( "GCW Error: No valid path found!...\n" )
			next_chose_location_name = p_loc
		else

			if #path >= 2 then
				next_chose_location_name = path[2].sys_name
			else
				next_chose_location_name = p_loc
			end

			--print out if desired
			local print_path = false
			if print_path then
				print("Starting at "..start_node.sys_name.." and going to "..method_goal)
				for i, node in ipairs ( path ) do
					print ( "Step " .. i .. " >> " .. node.sys_name )
				end
			end
		end

		ASTAR:clear_cached_paths()

		return next_chose_location_name

	end

	function GCW:PartitionPool(pool_total, max_num_stages, min_poolsize, partition_option)

		--set variables and default values
		pool_total = pool_total or 1
		local pool_remaining = pool_total
		max_num_stages = max_num_stages or 1
		min_poolsize = min_poolsize or 1
		partition_option = partition_option or "po_random"

		--partition pool
		local final_partition = {}

		local function GetMiddle()

			local middle_part = math.round(max_num_stages/2)
			if middle_part < 1 then
				middle_part = 1
			end
			if middle_part > max_num_stages then
				middle_part = max_num_stages
			end
			return middle_part

		end

		local function EvenPartition(stagetoexclude)

			stagetoexclude = stagetoexclude or 0

			for i=1,pool_total do
				local pool_si
				if min_poolsize <= pool_remaining then
					pool_si = min_poolsize
				else
					pool_si = pool_remaining
				end
				--account for pool totals that are small and == to stage index
				--for example if the total pool is 1 then the number to table index will always be 1
				--but if we are excluding that stage then it will never set, so add 1 then redo number to table index
				local stagesnindex = math.Number_to_Table_Index(i, max_num_stages)
				if stagetoexclude == stagesnindex then
					stagesnindex = stagesnindex + 1
					stagesnindex = math.Number_to_Table_Index(stagesnindex, max_num_stages)
				end
				if stagetoexclude ~= stagesnindex then
					pool_remaining = pool_remaining - pool_si
					local existingvalue = final_partition[stagesnindex] or 0
					final_partition[stagesnindex] = existingvalue + pool_si
				end
			end

			--fill in remaining slots with 0's
			for i=1,max_num_stages do
				if final_partition[i] == nil then
					final_partition[i] = 0
				end
			end

		end

		--debug checks
		if pool_total < 0 then
			print("Error, pool_total value within Partition Pool is " .. pool_total .. " which is below 0 . Assuming value of 1...\n")
			pool_total = 1
		end
		if max_num_stages < 1 then
			print("Error, max_num_stages value within Partition Pool is " .. max_num_stages .. " which is below 1 . Assuming value of 1...\n")
			max_num_stages = 1
		end
		if min_poolsize < 1 then
			print("Error, min_poolsize value within Partition Pool is " .. min_poolsize .. " which is below 1 . Assuming value of 1...\n")
			min_poolsize = 1
		end

		if string.find(partition_option, "only") ~= nil then --po_only_start, po_only_middle, or po_only_end
	
			local fill_parition_i
	
			if partition_option == "po_only_start" then
				fill_parition_i = 1 
			end
	
			if partition_option == "po_only_middle" then
				fill_parition_i = GetMiddle()
			end
	
			if partition_option == "po_only_end" then
				fill_parition_i = max_num_stages
			end
	
			for i=1,max_num_stages do
				local amount
				if fill_parition_i == i then
					amount = pool_total
				else
					amount = 0
				end
				final_partition[i] = amount
			end
	
		end

		if partition_option == "po_even" then
			--try to make partitions even based on min size and number of partitions

			EvenPartition(0)
			--[[
			for i, v in ipairs(final_partition) do
				print("Stage ".. i .. " Pool: ".. v)
			end
			--]]

		end

		if partition_option == "po_mixed" or partition_option == "po_random" then
			if pool_remaining > 0 then

				local methods = {}
				--mixed is mix between even and random
				if partition_option == "po_mixed" then
					table.insert(methods, "po_mixed")
				end
				table.insert(methods, "po_random")

				for _,v_methodstr in ipairs(methods) do
					if pool_remaining > 0 then
						for i=1,max_num_stages do
							local pool_si = 0
							if pool_remaining > 0 then
								if min_poolsize <= pool_remaining and (i < max_num_stages or v_methodstr == "po_mixed") then
									if v_methodstr == "po_mixed" then
										pool_si = min_poolsize
									else
										pool_si = ba.rand32(min_poolsize, pool_remaining)
									end
								else
									pool_si = pool_remaining
								end
							else
								pool_remaining = 0
							end
							pool_remaining = pool_remaining - pool_si
							local existingvalue = final_partition[i] or 0
							final_partition[i] = existingvalue + pool_si
						end
					end
				end
			end
		end

		--exclude option, ie "po_exclude_start" (first stage is excluded if there are more then 1 stage)
		if string.find(partition_option, "exclude") ~= nil then --"po_exclude_start" or "po_exclude_end"
			local exclude_stage = 0
			if max_num_stages > 1 then --can't exclude stages if there is only 1
				if string.find(partition_option, "start") then
					exclude_stage = 1
				end
				if string.find(partition_option, "middle") then
					exclude_stage = GetMiddle()
				end
				if string.find(partition_option, "end") then
					exclude_stage = max_num_stages
				end
			end
			EvenPartition(exclude_stage)
		end

		return final_partition

	end

	function GCW:PartitionList(tbl, PartitionPool_output) --takes a flat list and the output of Partition Pool then returns a partitioned list with that order

		--validity checks
		if tbl == nil then print("Error tbl argument for Partition List() is nil...\n") return end
		if PartitionPool_output == nil then print("Error Partition Pool_output argument for Partition List() is nil...\n") return end
		if type(tbl) ~= "table" then print("Error tbl argument for Partition List() is not a table...\n") return end
		if type(PartitionPool_output) ~= "table" then print("Error Partition Pool_output argument for Partition List() is not a table...\n") return end
		local ntbl = #tbl
		local num_partitions = #PartitionPool_output
		if ntbl <= 0 then print("Error tbl argument for Partition List() has no values...\n") return end
		if num_partitions <= 0 then print("Error Partition Pool_output argument for Partition List() has no values...\n") return end

		--make table with number of partitions
		local partitioned_list = {}
		for i=1,num_partitions do
			partitioned_list[i] = {}
		end

		--for each entry in flat list put in respective partition in partition table
		local current_tbl_i = 1
		local cumulative_partition = 0
		for i_parition_num, v_parition_amount in ipairs(PartitionPool_output) do
			if v_parition_amount > 0 then
				cumulative_partition = cumulative_partition + v_parition_amount
				--print("current_tbl_i, cumulative_partition "..current_tbl_i..", "..cumulative_partition)
				for i=current_tbl_i, cumulative_partition do
					table.insert(partitioned_list[i_parition_num], tbl[i])
					--print("Adding object "..tbl[i].." to stage "..i_partition_num)
					current_tbl_i = current_tbl_i + 1
				end
			end
		end

		--example of how Partition Pool() and Partition List() work
		--[[
		local t = {"a", "b"}
		local p = Partition Pool(#t, 4, 1)
		local pp = Partition List(t,p)
		for i,v in ipairs(pp) do
			print("Stage " .. i .. ": ")
			for k,vv in ipairs(v) do
				print(vv)
			end
		end
		--]]

		return partitioned_list

	end

	function GCW:PBH_to_3x3Matrix_forFRED(pbh, isstringoutput) --pbh should = {p,b,h} in degrees. Doesn't work super well with high bank values

		if isstringoutput == nil then 
			isstringoutput = false
		end

		if #pbh ~= 3 or type(pbh) ~= "table" then
			pbh = {0,0,0}
			self:warning("input to PBH to 3x3Matrix forFRED() is not a list of three numbers...\n")
		end

		local p = math.rad(pbh[1])
		local b = math.rad(pbh[2])
		local h = math.rad(pbh[3])

		local sinp = math.sin(p)
		local cosp = math.cos(p)
		local sinb = math.sin(b)
		local cosb = math.cos(b)
		local sinh_ = math.sin(h)
		local cosh_ = math.cos(h)
		local sbsh = sinb*sinh_
		local cbch = cosb*cosh_
		local cbsh = cosb*sinh_
		local sbch = sinb*cosh_

		local vals ={
			cbch + (sinp*sbsh), --1
			(sinp*cbsh) - sbch, --2
			sinh_*cosp, --3
			sinb*cosp, --4
			cosb*cosp, --5
			-sinp, --6
			sinp*sbch - cbsh,--7
			sbsh + (sinp*cbch), --8
			cosh_*cosp--9
		}

		--round to 6 decimal places
		for i,v in ipairs(vals) do
			vals[i] = math.round(v,6)
		end

		local finalm = {{vals[1],vals[4],vals[7]},{vals[2],vals[5],vals[8]},{vals[3],vals[6],vals[9]}}

		--do option of making into nice looking strings
		if isstringoutput then
			for i=1,#finalm do
				for j=1,#finalm[i] do
					finalm[i][j] = string.format("%.6f", finalm[i][j])
				end
			end
		end

		return finalm

	end

	function GCW:CurrentCampaign() --returns currently selected campaign as string

		local ply = ba.getCurrentPlayer() --gets player handle
		local c_file_name = ply:getCampaignFilename() --calls campaign filename
		--ba.getCurrentPlayer():getCampaignFilename() --this is the shorthand if I ever want to not use this function
		--print("Current campaign is: "..c_file_name.."...\n")
