	end

	function GCW:DrawString_oo(str, pos_oo, alignment_x)

		local coord = FotG:Get_Coordinates(pos_oo)
		local x = coord.x
		local y = coord.y

		if alignment_x == "right" then
			local str_width = gr.getStringWidth(str)
			x = x - str_width
		end
		if alignment_x == "center" then
			local str_width = gr.getStringWidth(str)
			x = x - str_width/2
		end
		gr.drawString(str, x, y)

	end

	function GCW:Ply_Calls_Reinforcements(team)

		if team == "Friendly" and self.data.player.rank <= 1 then
			return true
		else
			return false
		end

	end

	function GCW:Get_Allegiance_Change_Str(add_prefix)

		local ply = self.data.player
		local map = self.data.map_progress

		--if this is running in the command briefing that means we 
		--need to look up the most recent previous mission, not the current mission

		local previous_m_list = ply.previous_m_info
		if previous_m_list == nil then 
			return "" 
		end
		if previous_m_list[1] == nil then
			return ""
		end
		local most_recent_previous_mloc = previous_m_list[1].m_saved_location

		if most_recent_previous_mloc == nil then
			return ""
		end

		local planet_info = self.planets[most_recent_previous_mloc]

		local location_map = map[most_recent_previous_mloc]
		local allegiance_current = location_map.allegiance_score_current
		local allegiance_previous = location_map.allegiance_score_previous

		if allegiance_current == allegiance_previous then 
			return "" 
		end

		local change_text

		local support_str_info = self.cv.faction_support_strings[self.data.player.faction]

		local support_title = support_str_info.intext_usage
		local support_levels = support_str_info.legend_levels

		local l_friend, l_neutral, l_hostile = 1, 2, 3

		local function helper_text(l_from, l_to)
			return "from " .. string.lower(support_levels[l_from]) .. " to " .. string.lower(support_levels[l_to])
		end

		--hostile to neutral 
		--hostile to friendly
		if allegiance_previous < 0 then
			if allegiance_current == 0 then
				change_text = helper_text(l_hostile, l_neutral)
			elseif allegiance_current > 0 then 
				change_text = helper_text(l_hostile, l_friend)
			end
		end

		--friendly to neutral 
		--friendly to hostile 
		if allegiance_previous > 0 then
			if allegiance_current == 0 then
				change_text = helper_text(l_friend, l_neutral)
			elseif allegiance_current < 0 then 
				change_text = helper_text(l_friend, l_hostile)
			end
		end

		--neutral to hostile 
		--neutral to friendly
		if allegiance_previous == 0 then
			if allegiance_current < 0 then
				change_text = helper_text(l_neutral, l_hostile)
			elseif allegiance_current > 0 then 
				change_text = helper_text(l_neutral, l_friend)
			end
		end

		local final_txt = ""
		if change_text ~= nil and change_text ~= "" then
			--Following the outcome of the previous mission, the status of Hoth has now shifted to "" to the Alliance/Empire/Organization. 
			local pre_tbl = {
				{"Following the outcome of the previous mission, "},
			}
			local mid = support_title.." in the "..planet_info.display_name.." system has shifted "..change_text.."."
			if add_prefix then
				final_txt = math.Random_fromTable(pre_tbl) .. mid
			else
				final_txt = mid
			end
		end

		return final_txt

	end

	function GCW:Get_Persisent_Update_String(add_prefix)

		--gets string in format following:
		--  Alliance command reports the following updates on Vanguard Group: 
		--  XX were lost, YY were assigned to another group, and ZZ were recruited. 

		local ply = self.data.player
	
		local recruit_list = self.data.player.recruited_big_list or {}
		local retired_list = self.data.player.retired_big_list or {}

		--prep new list
		local new_list = {}
		for _,v_sname in ipairs(recruit_list) do
			local gcws = self.data.ships[v_sname]
			if gcws ~= nil then
				table.insert(new_list, {"", gcws.callsign, gcws.class})
			end
		end

		--prep lost and reassigned lists
		local lost_list = {}
		local reassigned_list = {}
		for _,v_info in ipairs(retired_list) do
			if v_info.retired_s_callsign ~= nil and v_info.retired_s_callsign ~= "" then
				if v_info.retired_s_dead then
					table.insert(lost_list, {"", v_info.retired_s_callsign, v_info.retired_s_class})
				else
					table.insert(reassigned_list, {"", v_info.retired_s_callsign, v_info.retired_s_class})
				end
			end
		end

		local function str_helper(s_list, word_type)
			--make format <X, Y, and Z were lost.>
			local num_ships = #s_list
			if num_ships > 0 then
				local list_str = self:ListShips(s_list, false, false, false)
				local w_word = " were "
				if num_ships == 1 then
					w_word = " was "
				end
				return list_str .. w_word .. word_type
			else
				return ""
			end
		end

		--list out
		local big_lost_str = str_helper(lost_list, "lost. ")
		local big_reassigned_str = str_helper(reassigned_list, "reassigned to a different group. ")
		local big_recruits_str = str_helper(new_list, "assigned to this group. ")

		--combine
		local prefix = ""
		local prefix_opts = {"Following the outcome of the previous mission, "}
		if add_prefix then 
			prefix = math.Random_fromTable(prefix_opts)
		end

		local per_f_group = self.objects.ship_framework.ply_and_non_same_facs.big.f1[ply.faction].base_names_tbl[1]

		local string_base_opts = {
			r = prefix .. "$f Alliance $f Command reports the following updates on $f "..per_f_group.." $f Squadron. ",
			e = prefix .. "$f Imperial $f Command reports the following updates on $f "..per_f_group.." $f Squadron. ",
			p = prefix .. "$f Leadership reports the following updates on $f "..per_f_group.." $f Squadron. ",
		}

		if big_lost_str == "" or big_reassigned_str == "" or big_recruits_str == "" then
			return ""
		else
			return string_base_opts[ply.faction] .. big_lost_str .. big_reassigned_str .. big_recruits_str
		end

	end

	function GCW:ChooseHostileFaction(mission_type, mission_location)

		--setup variables and get information about system
		local ply = self.data.player

		--get default hostile
		local default_hostile_fac = self:tget(mission_type, {"mission_meta", "hostile_faction_default_tbl", ply.faction}, "random_weighted")

		--get commander hostile if applicable/needed
		local hostile_cmd_fac
		if ply.campaign_goal_typ == "objective_KillCommander" then
			local hos_cmd_info = ply.commanders_info.Hostile
			if mission_location == hos_cmd_info.leader_location_true then
				hostile_cmd_fac = hos_cmd_info.leader_faction
			end
		end

		--get location info
		local location_info = self.data.map_progress[mission_location]
		if location_info == nil then
			self.warning("Location does not exist in map progress, problem location is "..tostring(mission_location), true)
			location_info = {}
		end
		local next_loc_alleg = location_info.allegiance_score_current or 0
		local fac_controlling_system = location_info.controlling_faction_current or ""

		--case of following:
			--chasing hostile pirate commander, and you attack the system they are at in SystemA, 
			--but they escape and all the surrounding systems are hostile but Imperial controlled

			--Given attacking Imperial controlled systems will only spawn Imperials as the hostile faction, 
			--how will player ever get a shot at spawning and killing the pirate commander?

			--In this case player needs to be able to spawn pirate commander in an escort attack or escort defense?
			--Code should only allow doing escort attack or defense as first options to ensure it's possible to spawn pirate commander.

			--Player could protect friendly escort, in which case hostile pirate shows up and attacks, 
			--even though system is Imperial controlled. 

			--Player could attack pirate escort, in which case hostile pirate is present even though system is Imperial controlled.

		--location fac control is open (0 allegiance)
			--player is defending 
				--> hostile faction uses m_type faction choice
			--player is attacking 
				--> hostile faction uses m_type faction choice
		--location fac is controlled by player faction (+ allegiance)
			--player is defending 
				--> hostile faction uses m_type faction choice
			--player is attacking 
				--> hostile faction uses m_type faction choice (likely hostile escort is passing through player system)
		--location fac is controlled by non-player faction (- allegiance)
			--player is defending 
				--> hostile faction uses location faction (likely player is doing an escort passing through)
			--player is attacking 
				--> hostile faction uses location faction 

		--By default hostile faction follows logic above:
		--  If hostile system use that controlling faction as the hostile faction
		--  otherwise, use the default hostile weighted function.
		--  But, use commander hostile faction if needed and able.
		local selected_hostile_faction
		local mission_valid_as_option = true --NAV_HELP 37814

		if (next_loc_alleg < 0) and fac_controlling_system ~= nil and fac_controlling_system ~= "" then
			--if hostile system with valid controlling faction, then hostile should be controlling faction 
			--but check if commander override needed and able, and if so then force commander faction
			local hostile_overrideable = self:tget(mission_type, {"mission_meta", "allow_special_hostile_override"})
			local hos_cmd_valid = (hostile_cmd_fac ~= nil and hostile_cmd_fac ~= "")
			if hos_cmd_valid and hostile_overrideable then
				selected_hostile_faction = hostile_cmd_fac
			else
				selected_hostile_faction = fac_controlling_system
			end
			--Example, as rebels we are hunting a pirate that runs to an Imperial System
			--normally hostile faction would be Imperial, but we need it to be Pirate if mission type allows

			--do not add mission to possible option at this point if hos cmd and hos fac are different
			--in other words, only add missions that hos cmd can be found on for this location 
			if hos_cmd_valid and selected_hostile_faction ~= hostile_cmd_fac then
				mission_valid_as_option = false --NAV_HELP 37814
			end
		else
			--system is friendly or neutral or somehow invalid hostile, so hostile can be anyone easily
			--prefer hostile commander if needed, otherwise use weighted choice from mission type 
			selected_hostile_faction = hostile_cmd_fac or default_hostile_fac
		end

		return selected_hostile_faction, mission_valid_as_option

	end

	function GCW:GetControllingFaction(allegiance_score, hostile_faction)

		local sys_faction = ""

		if allegiance_score > 0 then
			sys_faction = self.data.player.faction
		elseif allegiance_score < 0 then
			if hostile_faction ~= nil then
				sys_faction = hostile_faction
			else
				sys_faction = math.Random_Weighted(self.cv.default_h_fac_for_defend_mission[self.data.player.faction])
			end
		elseif allegiance_score == 0 then
			sys_faction = ""
		end

		return sys_faction

	end

	function GCW:MakePlanetPlayerTbl(score_range)

		--clear/initiate
		self.data.map_progress = nil
		self.data.map_progress = {}
		score_range = score_range or self.cv.map_allegiance_score_caps

		for k_pID, _ in pairs(self.planets) do --v_p_info
			local allegiance = ba.rand32(score_range[1], score_range[2])
			--^^more negative is more hostile and more positive is friendly 
			local fac = self:GetControllingFaction(allegiance)
			self.data.map_progress[k_pID] = {
				allegiance_score_current = allegiance,
				allegiance_score_previous = allegiance,

				most_recent_mission_type = "",
				most_recent_mission_outcome = "",

				controlling_faction_current = fac,
				controlling_faction_previous = fac
			}
		end

		--Notes on allegiance score:
		--Use allegiance score in addition to pool size for choosing mission types. For example, with a very hostile system we can still attack with small attacks..
		--..b/c we always need to be able to move through the system. Just because we can move through it though doesn't mean we should be easily able to capture it.
		--In other words, do not use pool size as allegiance factor. IE -10 to -8 means we can never do or move through that location if we have small/no per fleet.
		--With allegiance score we can do attack (since small attacks exist) and we still take a lot to capture the system. 

	end

